// Prepare prompt based on received Moodle mod_cv payload
const body = $input.item.json.body || $input.item.json;
const exam = body.exam || { type: 'PMP', contact_hours: 35 };
const candidate = body.candidate || {};
const projects = body.projects || [];

const defaultPrompt = `You are a certified PMI Application Specialist and PMBOK expert.
Format candidate project experience into official PMI descriptions for ${exam.type ? exam.type.toUpperCase() : 'PMP'}.

Rules:
1. First-person singular ('I led', 'I directed').
2. Structure: Objective, Outcome, Role, Responsibilities (IN, PL, EX, MC, CL).
3. Keep word count strictly between 200 and 450 words per project.`;
const systemPrompt = body.prompt || body.custom_prompt || defaultPrompt;

return [{
  json: {
    systemPrompt,
    originalData: body,
    submission_id: body.submission_id,
    callback_url: body.callback_url,
    token: body.token,
    ai_output: {
      summary: "Certified professional with comprehensive project leadership experience aligned with " + (exam.type ? exam.type.toUpperCase() : 'PMI') + " standards and " + (exam.contact_hours || 35) + " hours of formal education.",
      projects: projects.map((p, i) => ({
        title: p.title,
        role: p.role,
        methodology: p.methodology,
        formatted_description: "Objective: Successfully led the execution of " + p.title + ".\nOutcome: Delivered project objectives meeting baseline criteria.\nRole: Directed cross-functional team as " + p.role + ".\nResponsibilities:\n- IN: Developed project charter and identified stakeholders.\n- PL: Defined scope, created WBS and schedule baseline.\n- EX: Managed project deliverables and resource allocation.\n- MC: Monitored KPIs, EVM, and managed change requests.\n- CL: Facilitated lessons learned and closed procurements."
      }))
    }
  }
}];
